import fs from 'fs';
import path from 'path';
import { createLogger } from './logger';

const log = createLogger('UiDistPath');

const resolveUiPath = (): string => {
  const bundledPath = path.join(__dirname, '..', 'ui/dist');

  const devPath = path.join(__dirname, '../../src/ui/dist');

  if (fs.existsSync(bundledPath)) {
    log.debug(`Using bundled UI path: ${bundledPath}`);
    return bundledPath;
  }

  log.debug(`Using development UI path: ${devPath}`);
  return devPath;
};

export const DIST_UI_PATH = resolveUiPath();
